import json,pathlib,collections
base=pathlib.Path(r'C:\Users\Dell\Desktop\Quant\lse_catalog_snapshot')
files=sorted(base.glob('lse_catalog_*.json'))
for f in files:
 d=json.loads(f.read_text(encoding='utf-8')); rows=d['catalog']; keys={(r.get('dataset'),r.get('symbol')) for r in rows}; cats=collections.Counter(r.get('category') for r in rows)
 print(f.name,d.get('retrieved_at_utc'),len(rows),len(keys),dict(sorted(cats.items())))
if len(files)>=2:
 a=json.loads(files[-2].read_text(encoding='utf-8'))['catalog']; b=json.loads(files[-1].read_text(encoding='utf-8'))['catalog']
 ka={(r.get('dataset'),r.get('symbol')) for r in a};kb={(r.get('dataset'),r.get('symbol')) for r in b}
 print('new keys',len(kb-ka),'removed keys',len(ka-kb))
 changes=[]
 amap={(r.get('dataset'),r.get('symbol')):r for r in a}
 for r in b:
  k=(r.get('dataset'),r.get('symbol'))
  if k in amap and any(amap[k].get(x)!=r.get(x) for x in ('first','last','ticks','country','name')):
   changes.append((k,amap[k],r))
 print('metadata changed keys',len(changes))
 for k,x,y in changes[:8]:print(k,'ticks',x.get('ticks'),y.get('ticks'),'last',x.get('last'),y.get('last'),'country',x.get('country'),y.get('country'))
'@ | python -

